//! Designated host for the generated `BaseMath` simulation CLI — HAND-WRITTEN.
//!
//! The CLI body is generated by the `language!` macro into
//! `target/generated/basemath/simulate.rs` (`options { emit_simulator: true }`, the
//! default) and materialized here by the `basemath_simulation_main!` wrapper. This file is
//! the cargo `[[bin]]` target; its stanza lives in `languages/Cargo.toml`.
//!
//! The wrapper takes the definition's module path because only a host knows it. `BaseMath`
//! is a LIBRARY module, so it is named through the library.

mettail_languages::basemath_simulation_main!(mettail_languages::basemath);
